implementationPlan.description:
Fix RunDetailPage.tsx (lines 89-101): Remove `runQuery.data` from the dependency array. Use a ref to access current data:
```typescript
const runDataRef = useRef(runQuery.data);
runDataRef.current = runQuery.data;

useEffect(() => {
    if (!latestEvent || !runId) return;
    const runMatch = latestEvent.runId === runId;
    const jobMatch = latestEvent.jobId
        ? Object.values(runDataRef.current?.steps || {}).some(step => step.job_id === latestEvent.jobId)
        : false;
    if (runMatch || jobMatch) {
        queryClient.invalidateQueries({ queryKey: ["run", runId] });
        queryClient.invalidateQueries({ queryKey: ["timeline", runId] });
    }
}, [latestEvent, runId, queryClient]);
```
